#!/usr/bin/env python3
"""Nature (tarantula + fish/shark), recent history, metrology/aerospace science plates."""
from __future__ import annotations

import json
import random
from pathlib import Path

RNG = random.Random(20260919)
OUT = Path("/workspace/src/game/banks")


def js(s: str) -> str:
    return json.dumps(s, ensure_ascii=False)


def plate_text(s: str) -> str:
    out = []
    for ch in s.lower().replace("’", "'"):
        out.append(ch if ch.isalnum() else " ")
    return " ".join("".join(out).split())


def leaks(prompt: str, answer: str) -> bool:
    q = plate_text(prompt)
    a = plate_text(answer)
    if len(a) < 4:
        return False
    return f" {q} ".find(f" {a} ") >= 0


class Rows:
    def __init__(self) -> None:
        self.rows: list[tuple[str, list[str], str, int]] = []
        self.seen: set[str] = set()

    def add(self, prompt: str, choices: list[str], answer: str, diff: int) -> None:
        if not isinstance(prompt, str) or not isinstance(answer, str) or not isinstance(choices, (list, tuple)):
            return
        if prompt in self.seen or leaks(prompt, answer):
            return
        if answer not in choices or len(choices) != 4 or len(set(choices)) != 4:
            return
        self.seen.add(prompt)
        self.rows.append((prompt, list(choices), answer, diff))

    def fact(self, prompt: str, answer: str, choices: list[str], diff: int) -> None:
        """Rows are stored as (prompt, answer, choices, diff) in the source lists."""
        self.add(prompt, list(choices), answer, diff)

    def mc(self, prompt: str, answer: str, pool: list[str], diff: int) -> None:
        others = [x for x in pool if x != answer]
        if len(others) < 3:
            return
        RNG.shuffle(others)
        ch = [answer, others[0], others[1], others[2]]
        RNG.shuffle(ch)
        self.add(prompt, ch, answer, diff)


def emit(path: Path, export: str, rows: list) -> None:
    lines = [
        'import { q } from "../quiz";',
        'import type { TriviaQ } from "../types";',
        "",
        f"export const {export}: TriviaQ[] = [",
    ]
    for prompt, choices, answer, diff in rows:
        ch = ", ".join(js(c) for c in choices)
        lines.append(f"  q({js(prompt)}, [{ch}], {js(answer)}, {diff}),")
    lines.append("];")
    lines.append("")
    path.write_text("\n".join(lines) + "\n")
    print("wrote", path.name, "n=", len(rows))


